document.querySelectorAll('form[data-print-form]').forEach((form)=>{form.addEventListener('submit',()=>{const next=form.dataset.thanks;if(next){let redirect=form.querySelector('input[name="_next"]');if(!redirect){redirect=document.createElement('input');redirect.type='hidden';redirect.name='_next';form.appendChild(redirect)}redirect.value=new URL(next,window.location.href).href}})});document.querySelectorAll('[data-copy]').forEach((button)=>{button.addEventListener('click',async()=>{const value=button.dataset.copy||'';try{await navigator.clipboard.writeText(value);const original=button.textContent;button.textContent='Copied';setTimeout(()=>{button.textContent=original},1500)}catch{}})});document.querySelectorAll('details[data-exclusive]').forEach((details)=>{details.addEventListener('toggle',()=>{if(details.open){document.querySelectorAll('details[data-exclusive]').forEach((other)=>{if(other!==details)other.open=false})}})});document.querySelectorAll('.menu-toggle').forEach((button)=>{button.addEventListener('click',()=>{const menu=document.getElementById(button.getAttribute('aria-controls'));const open=menu?.classList.toggle('is-open');button.setAttribute('aria-expanded',String(Boolean(open)))})});document.addEventListener('click',(event)=>{const openMenu=document.querySelector('.menu-panel.is-open');if(!openMenu||openMenu.contains(event.target)||event.target.closest('.menu-toggle'))return;openMenu.classList.remove('is-open');const button=document.querySelector('.menu-toggle');button?.setAttribute('aria-expanded','false')});(()=>{const header=document.querySelector('.header');if(!header)return;const top=header.querySelector('.top');if(!top||top.dataset.pageMenuReady==='true')return;top.dataset.pageMenuReady='true';const nav=top.querySelector('.nav');const lang=top.querySelector('.lang');const toggle=document.createElement('button');toggle.type='button';toggle.className='menu-toggle';toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-controls','site-menu');toggle.innerHTML='Menu <span class="menu-toggle-caret" aria-hidden="true"></span>';const panel=document.createElement('div');panel.className='menu-panel';panel.id='site-menu';if(nav){nav.remove();panel.append(nav)}if(lang){lang.remove();panel.append(lang)}top.append(toggle,panel)})();(()=>{const path=window.location.pathname.replace(/\/$/,'');const match=path.match(/^\/(en|es|pt-br|fr|de|it|ja|ko|zh)(?:\/(.*))?$/);if(!match)return;const locale=match[1];document.querySelectorAll('a').forEach((link)=>{const href=link.getAttribute('href')||'';const policy=href.match(/(?:^|\/)(privacy-policy|refund-policy|billing-policy)(?:\.html)?\/?$/);if(policy)link.href=`/${locale}/${policy[1]}`})})();